          var sigs = {};
          ["choose", "blank", "match", "games"].forEach(function (pk) {
            (t.pools[pk] || []).forEach(function (g) {
              for (var i = 0; i < 12; i++) { try { sigs[qSig4(g())] = 1; } catch (e) {} }
            });
          });
          bankN = Object.keys(sigs).length;
